1. public Response doExecute(NodeE node, OnlineReportVO operateData) {
2.         OrderE orderE = node.getOrder();
3.         String reportNo = orderE.getOrderNo();
4.         String policyNo = orderE.getBizCode();
5.         OrderE existOrderE = orderRepository.getOrderWithBizCode(reportNo, policyNo, null);
6.         if (existOrderE != null && existOrderE.getStatus().getCode().equals(StatusV.SUCCESS.getCode())) {
7.             OnlineReportResponse response = new OnlineReportResponse();
8.             response.setMiddleClaimReport(operateData.getMiddleClaimReport());
9.             return Response.ofSuccess(response);
10.         }
11.         OnlineReportVO onlineReportVO = orderE.getBizData();
12.         ClaimDocUploadConfigInfo configInfo = onlineReportVO.getMiddleClaimReport().getConfigInfo();
13.         String productCode = configInfo.getProductCode();
14.         PolicyInfo policyInfo = onlineReportVO.getMiddleClaimReport().getPolicyInfo();
15.         NodeE reportInfoNodeE = orderE.getNodeEList().stream().filter(x -> NodeTypeV.CLAIM_REPORT_MAIN.equals(x.getNodeType())).findFirst().orElse(null);
16.         NodeE claimAccountInfoNodeE = orderE.getNodeEList().stream().filter(x -> NodeTypeV.CLAIM_REPORT_ACCOUNT.equals(x.getNodeType())).findFirst().orElse(null);
17.         if (reportInfoNodeE != null && claimAccountInfoNodeE != null) {
18.             ReportInfo onlineReportInfo = reportInfoNodeE.getBizData();
19.             InsuredClaimInfo insuredClaimInfo = onlineReportInfo.getInsuredClaimInfo();
20.             insuredClaimInfo.setPolicyNo(policyNo);
21.             insuredClaimInfo.setRelatedPolicyNo(onlineReportVO.getMiddleClaimReport().getPolicyInfo().getRelatedPolicyNo());
22.             insuredClaimInfo.setProductCode(policyInfo.getProductCode());
23.             insuredClaimInfo.setReportNo(reportNo);
24.             onlineReportInfo.setInsuredClaimInfo(insuredClaimInfo);
25.             LOGGER.info("提交在线报案信息: onlineReportInfo :{}", JSON.toJSONString(onlineReportInfo));
26.             //提交报案
27.             try {
28.                 reportInfoRepository.addReport(onlineReportInfo);
29.             } catch (EclipseException e){
30.                 throw e;
31.             }catch (Exception e) {
32.                 LOGGER.error("报案号【{0}】,提交在线报案信息异常:{1}", reportNo, e);
33.                 String errMsg = MessageFormat.format("报案号【{0}】,提交在线报案信息异常:{1}", reportNo, e.getMessage());
34.                 LOGGER.error(errMsg);
35.                 MonitorLoggerUtils.monitor("", EC_024_024.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
36.                 ExceptionUtils.throwFailureException(ErrorEnum.SYS_INNER_DATA_ERROR, "您的报案信息不完整,请更正后重新报案");
37.             }
38.             //提交理赔账户信息
39.             ClaimAccountInfo claimAccountInfo = claimAccountInfoNodeE.getBizData();
40.             claimAccountInfo.setPolicyNo(policyNo);
41.             claimAccountInfo.setReportNo(reportNo);
42.             if(StrUtil.isNotBlank(insuredClaimInfo.getProductCode()) && GROUP_PRODUCT_CODE.contains(insuredClaimInfo.getProductCode())){
43.                 //员福产品报案，传给理赔保单号是大团单号
44.                 claimAccountInfo.setPolicyNo(insuredClaimInfo.getRelatedPolicyNo());
45.             }
46. 
47.             LOGGER.info("提交理赔账户信息: claimAccountInfo :{}", JSON.toJSONString(claimAccountInfo));
48.             try {
49.                 reportInfoRepository.addPayee(claimAccountInfo);
50.             } catch (Exception e) {
51.                 LOGGER.error("报案号【{0}】,提交理赔账户信息异常:{1}", reportNo, e);
52.                 String errMsg = MessageFormat.format("报案号【{0}】,提交理赔账户信息异常:{1}", reportNo, e.getMessage());
53.                 LOGGER.error(errMsg);
54.                 MonitorLoggerUtils.monitor("", EC_024_025.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
55.             }
56.             //提交理赔申请书信息
57.             ClaimApplyBookInfo applyBook = operateData.getMiddleClaimReport().getClaimApplyBookInfo();
58.             String signImgBase64 = applyBook.getSingImgBase64();
59.             LOGGER.info("提交理赔申请书信息: applyBook :{}", JSON.toJSONString(applyBook));
60.             MiddleReportVO paramOfReportConfig = new MiddleReportVO();
61.             paramOfReportConfig.setReportInfo(onlineReportInfo);
62.             //根据脚本获取单证模板code
63.             LOGGER.info("获取单证模板号 paramOfReportConfig:{},productCode:{}", JSON.toJSONString(paramOfReportConfig), productCode);
64.             String docTplNo = reportConfigRepository.getClaimApplyBookTplCode(paramOfReportConfig, productCode);
65.             //构建单证模板
66.             String docTpl = this.buildDocTpl(policyInfo, onlineReportInfo, applyBook, signImgBase64);
67.             //调用单证生成理赔申请书
68.             byte[] applyBookByte = null;
69.             try {
70.                 LOGGER.info("构建单证模板 reportNo:{},docTplNo:{}", reportNo, docTplNo);
71.                 InputStream applyBookInStream = documentRepository.generateClaimApplicant(signImgBase64, reportNo, docTpl, docTplNo);
72.                 applyBookByte = FileUtil.getBytes(applyBookInStream);
73.             } catch (Exception e) {
74.                 LOGGER.error("报案号【{0}】,调用单证生成理赔申请书异常:{1}", reportNo, e);
75.                 String errMsg = MessageFormat.format("报案号【{0}】,调用单证生成理赔申请书失败:{1}", reportNo, e.getMessage());
76.                 LOGGER.error(errMsg);
77.                 MonitorLoggerUtils.monitor("", EC_024_026.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
78.             }
79.             //调用影像上传单证
80.             Set<String> tags = new LinkedHashSet<>(Arrays.asList(DOC_CLAIM_APPLY_BOOK_CATALOG_CODE.substring(0, 3), DOC_CLAIM_APPLY_BOOK_CATALOG_CODE));
81.             try {
82.                 claimImageRepository.imageUpload(reportNo, CLAIM_APPLY_BOOK_FILE_TYPE, APPLET_CLAIM_APPLY_BOOK_NAME, applyBookByte, tags, getDocSystemSourceByAppInfo(node.getOrder().getAppCode()));
83.             } catch (Exception e) {
84.                 LOGGER.error("报案号【{0}】,上传理赔申请书异常:{1}", reportNo, e);
85.                 String errMsg = MessageFormat.format("报案号【{0}】,上传理赔申请书失败:{1}", reportNo, e.getMessage());
86.                 LOGGER.error(errMsg);
87.                 MonitorLoggerUtils.monitor("", EC_024_027.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
88.             }
89.             //提交影像
90.             try {
91.                 claimDocUploadRepository.submitImage(operateData.getMiddleClaimReport().getReportNo(), "");
92.             } catch (Exception e) {
93.                 LOGGER.error("报案号【{0}】,提交影像异常:{1}", operateData.getMiddleClaimReport().getReportNo(), e);
94.                 String errMsg = MessageFormat.format("报案号【{0}】,提交影像失败:{1}", operateData.getMiddleClaimReport().getReportNo(), e.getMessage());
95.                 LOGGER.warn(errMsg);
96.                 MonitorLoggerUtils.monitor("", EC_024_029.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
97.             }
98.         } else {
99.             ExceptionUtils.throwFailureException(ErrorEnum.ECLIPSE_FRONT_DATA_ERROR, "您的报案信息不完整,请补充后报案");
100.         }
101.         node.execute();
102.         node.submit();
103.         //完成Order
104.         OrderE order = node.getOrder();
105.         order.finish();
106.         order.submit();
107. 
108.         //发送报案完成事件
109.         ClaimOrderE claimOrderE = new ClaimOrderE();
110.         claimOrderE.setOrderNo(order.getOrderNo());
111.         claimOrderE.setEventType(OrderEventEnum.CLAIM_FINISH);
112.         claimOrderE.setStatus(order.getStatus());
113.         claimOrderE.setFinishTime(order.getFinishTime());
114. 
115.         ClaimOrderEvent claimOrderEvent = new ClaimOrderEvent(JSON.toJSONString(claimOrderE));
116.         domainEventGateway.publishClaimOrderFinishedEvent(claimOrderEvent);
117.         LOGGER.info("publishClaimOrderFinishedEvent : {}", claimOrderEvent);
118. 
119.         OnlineReportResponse response = new OnlineReportResponse();
120.         response.setMiddleClaimReport(operateData.getMiddleClaimReport());
121.         return Response.ofSuccess(response);
122.     }
```

