56.                     new ParameterizedTypeReference<GenericResponse<ImageFileDTO>>() {
57.                     });
58.             if (response == null || response.getBody() == null || response.getStatusCodeValue() != HttpStatus.OK.value()) {
59.                 log.warn("uploadImage failed, response is {}, with uploadFileRequest is {}", response, fileRequest);
60.                 throw new EclipseRuntimeException(ErrorCodeEnum.ERROR_FILE_UPLOAD_FAIL, "调用影像系统发生异常");
61.             }
62. 
63.             // get Image File DTO
64.             return response.getBody().getData();
