public Response doExecute(NodeE node, OnlineReportVO operateData) {
        OrderE orderE = node.getOrder();
        String reportNo = orderE.getOrderNo();
        String policyNo = orderE.getBizCode();
        OrderE existOrderE = orderRepository.getOrderWithBizCode(reportNo, policyNo, null);
        if (existOrderE != null && existOrderE.getStatus().getCode().equals(StatusV.SUCCESS.getCode())) {
            OnlineReportResponse response = new OnlineReportResponse();
            response.setMiddleClaimReport(operateData.getMiddleClaimReport());
            return Response.ofSuccess(response);
        }
        OnlineReportVO onlineReportVO = orderE.getBizData();
        ClaimDocUploadConfigInfo configInfo = onlineReportVO.getMiddleClaimReport().getConfigInfo();
        String productCode = configInfo.getProductCode();
        PolicyInfo policyInfo = onlineReportVO.getMiddleClaimReport().getPolicyInfo();
        NodeE reportInfoNodeE = orderE.getNodeEList().stream().filter(x -> NodeTypeV.CLAIM_REPORT_MAIN.equals(x.getNodeType())).findFirst().orElse(null);
        NodeE claimAccountInfoNodeE = orderE.getNodeEList().stream().filter(x -> NodeTypeV.CLAIM_REPORT_ACCOUNT.equals(x.getNodeType())).findFirst().orElse(null);
        if (reportInfoNodeE != null && claimAccountInfoNodeE != null) {
            ReportInfo onlineReportInfo = reportInfoNodeE.getBizData();
            InsuredClaimInfo insuredClaimInfo = onlineReportInfo.getInsuredClaimInfo();
            insuredClaimInfo.setPolicyNo(policyNo);
            insuredClaimInfo.setRelatedPolicyNo(onlineReportVO.getMiddleClaimReport().getPolicyInfo().getRelatedPolicyNo());
            insuredClaimInfo.setProductCode(policyInfo.getProductCode());
            insuredClaimInfo.setReportNo(reportNo);
            onlineReportInfo.setInsuredClaimInfo(insuredClaimInfo);
            LOGGER.info("提交在线报案信息: onlineReportInfo :{}", JSON.toJSONString(onlineReportInfo));
            //提交报案
            try {
                reportInfoRepository.addReport(onlineReportInfo);
            } catch (EclipseException e){
                throw e;
            }catch (Exception e) {
                LOGGER.error("报案号【{0}】,提交在线报案信息异常:{1}", reportNo, e);
                String errMsg = MessageFormat.format("报案号【{0}】,提交在线报案信息异常:{1}", reportNo, e.getMessage());
                LOGGER.error(errMsg);
                MonitorLoggerUtils.monitor("", EC_024_024.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
                ExceptionUtils.throwFailureException(ErrorEnum.SYS_INNER_DATA_ERROR, "您的报案信息不完整,请更正后重新报案");
            }
            //提交理赔账户信息
            ClaimAccountInfo claimAccountInfo = claimAccountInfoNodeE.getBizData();
            claimAccountInfo.setPolicyNo(policyNo);
            claimAccountInfo.setReportNo(reportNo);
            if(StrUtil.isNotBlank(insuredClaimInfo.getProductCode()) && GROUP_PRODUCT_CODE.contains(insuredClaimInfo.getProductCode())){
                //员福产品报案，传给理赔保单号是大团单号
                claimAccountInfo.setPolicyNo(insuredClaimInfo.getRelatedPolicyNo());
            }

            LOGGER.info("提交理赔账户信息: claimAccountInfo :{}", JSON.toJSONString(claimAccountInfo));
            try {
                reportInfoRepository.addPayee(claimAccountInfo);
            } catch (Exception e) {
                LOGGER.error("报案号【{0}】,提交理赔账户信息异常:{1}", reportNo, e);
                String errMsg = MessageFormat.format("报案号【{0}】,提交理赔账户信息异常:{1}", reportNo, e.getMessage());
                LOGGER.error(errMsg);
                MonitorLoggerUtils.monitor("", EC_024_025.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
            }
            //提交理赔申请书信息
            ClaimApplyBookInfo applyBook = operateData.getMiddleClaimReport().getClaimApplyBookInfo();
            String signImgBase64 = applyBook.getSingImgBase64();
            LOGGER.info("提交理赔申请书信息: applyBook :{}", JSON.toJSONString(applyBook));
            MiddleReportVO paramOfReportConfig = new MiddleReportVO();
            paramOfReportConfig.setReportInfo(onlineReportInfo);
            //根据脚本获取单证模板code
            LOGGER.info("获取单证模板号 paramOfReportConfig:{},productCode:{}", JSON.toJSONString(paramOfReportConfig), productCode);
            String docTplNo = reportConfigRepository.getClaimApplyBookTplCode(paramOfReportConfig, productCode);
            //构建单证模板
            String docTpl = this.buildDocTpl(policyInfo, onlineReportInfo, applyBook, signImgBase64);
            //调用单证生成理赔申请书
            byte[] applyBookByte = null;
            try {
                LOGGER.info("构建单证模板 reportNo:{},docTplNo:{}", reportNo, docTplNo);
                InputStream applyBookInStream = documentRepository.generateClaimApplicant(signImgBase64, reportNo, docTpl, docTplNo);
                applyBookByte = FileUtil.getBytes(applyBookInStream);
            } catch (Exception e) {
                LOGGER.error("报案号【{0}】,调用单证生成理赔申请书异常:{1}", reportNo, e);
                String errMsg = MessageFormat.format("报案号【{0}】,调用单证生成理赔申请书失败:{1}", reportNo, e.getMessage());
                LOGGER.error(errMsg);
                MonitorLoggerUtils.monitor("", EC_024_026.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
            }
            //调用影像上传单证
            Set<String> tags = new LinkedHashSet<>(Arrays.asList(DOC_CLAIM_APPLY_BOOK_CATALOG_CODE.substring(0, 3), DOC_CLAIM_APPLY_BOOK_CATALOG_CODE));
            try {
                claimImageRepository.imageUpload(reportNo, CLAIM_APPLY_BOOK_FILE_TYPE, APPLET_CLAIM_APPLY_BOOK_NAME, applyBookByte, tags, getDocSystemSourceByAppInfo(node.getOrder().getAppCode()));
            } catch (Exception e) {
                LOGGER.error("报案号【{0}】,上传理赔申请书异常:{1}", reportNo, e);
                String errMsg = MessageFormat.format("报案号【{0}】,上传理赔申请书失败:{1}", reportNo, e.getMessage());
                LOGGER.error(errMsg);
                MonitorLoggerUtils.monitor("", EC_024_027.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
            }
            //提交影像
            try {
                claimDocUploadRepository.submitImage(operateData.getMiddleClaimReport().getReportNo(), "");
            } catch (Exception e) {
                LOGGER.error("报案号【{0}】,提交影像异常:{1}", operateData.getMiddleClaimReport().getReportNo(), e);
                String errMsg = MessageFormat.format("报案号【{0}】,提交影像失败:{1}", operateData.getMiddleClaimReport().getReportNo(), e.getMessage());
                LOGGER.warn(errMsg);
                MonitorLoggerUtils.monitor("", EC_024_029.name(), 0L, 1L, OUTSIDE_REMOTE_EXCEPTION.getErrorCode(), errMsg, reportNo);
            }
        } else {
            ExceptionUtils.throwFailureException(ErrorEnum.ECLIPSE_FRONT_DATA_ERROR, "您的报案信息不完整,请补充后报案");
        }
        node.execute();
        node.submit();
        //完成Order
        OrderE order = node.getOrder();
        order.finish();
        order.submit();

        //发送报案完成事件
        ClaimOrderE claimOrderE = new ClaimOrderE();
        claimOrderE.setOrderNo(order.getOrderNo());
        claimOrderE.setEventType(OrderEventEnum.CLAIM_FINISH);
        claimOrderE.setStatus(order.getStatus());
        claimOrderE.setFinishTime(order.getFinishTime());

        ClaimOrderEvent claimOrderEvent = new ClaimOrderEvent(JSON.toJSONString(claimOrderE));
        domainEventGateway.publishClaimOrderFinishedEvent(claimOrderEvent);
        LOGGER.info("publishClaimOrderFinishedEvent : {}", claimOrderEvent);

        OnlineReportResponse response = new OnlineReportResponse();
        response.setMiddleClaimReport(operateData.getMiddleClaimReport());
        return Response.ofSuccess(response);
    }

@Override
    public String imageUpload(String reportNo, String contentType, String fileName, byte[] content, Set<String> tags, Integer systemSource) {
        UploadFileRequest uploadFileRequest = new UploadFileRequest();
        uploadFileRequest.setBusinessNo(reportNo);
        uploadFileRequest.setMimeType(contentType);
        uploadFileRequest.setName(fileName);
        uploadFileRequest.setContent(content);
        uploadFileRequest.setTags(tags);
        uploadFileRequest.setSystemSource(systemSource);

        ImageFileDTO imageFileDTO = externalImageService.uploadImage(uploadFileRequest);
        return imageFileDTO.getUrl();
    }

