protected Integer getDocSystemSourceByAppInfo(String appCode) {
        if (StringUtils.isEmpty(appCode)) {
            log.warn("获取单证上传系统来源异常：【appCode为空】, 取默认配置");
            return RiskClassifySupportChannelEnum.OTHER.getCode();
        }

        //获取APP通用配置
        String configKey = String.format("%s_%s", CommonConfigConstants.APP, appCode);
        CommonConfigAppVO commonConfigAppVO = commonConfigObjectService.getObject(configKey, config -> JSON.parseObject(config, CommonConfigAppVO.class));
        if (commonConfigAppVO == null) {
            String errMsg = MessageFormat.format("获取单证上传系统来源异常：【app配置表无appCode:{0}的配置信息】, 取默认配置", appCode);
            log.warn(errMsg);
            return RiskClassifySupportChannelEnum.OTHER.getCode();
        }

        if (commonConfigAppVO.getDoc() == null || commonConfigAppVO.getDoc().getImgSystemSource() == null) {
            String errMsg = MessageFormat.format("获取单证上传系统来源异常：【app配置表无appCode:{0}的单证配置信息】, 取默认配置", appCode);
            log.warn(errMsg);
            return RiskClassifySupportChannelEnum.OTHER.getCode();
        }

        return commonConfigAppVO.getDoc().getImgSystemSource();
    }

