@Service
@Slf4j
@Setter
public class ExternalImageServiceImpl implements ExternalImageService, InitializingBean {

    //履约域-报案
    private static final String BUSINESS_TYPE = "10000";

    //6个小时
    private static final long SIX_HOUR_TO_MILLISECOND = 6 * 60 * 60 * 1000;

    private static final String IMAGE_TAIL = "v1/files/uploadWithPassword";

    /**
     * 文件名最大长度
     */
    private static final int MAX_FILE_NAME_LENGTH = 60;
    private static final String IMAGE_FILE_JPG = "ImageFile.jpg";
    /**
     * 待分类目录
     */
    private static final String C_TYPE_SORTING = "C_TYPE_SORTING";
    /**
     * systemUserId
     */
    @Value("${eclipse.external.image.file.system.user.id}")
    private String systemUserId;
    /**
     * password
     */
    @Value("${eclipse.external.image.file.password}")
    private String password;

    @Value("${eclipse.external.image.file}")
    private String imageUploadUrl;

    @Inject
    @Named("fileRestTemplate")
    private RestTemplate fileRestTemplate;

    @Inject
    private ImageFileService imageFileService;

    /**
     * claimSupportService
     */
    @javax.annotation.Resource
    private ClaimSupportService claimSupportService;

    @javax.annotation.Resource
    private ImageCategoryService imageCategoryService;

    /**
     * 创建定时线程池
     */
    private ScheduledExecutorService service = new ScheduledThreadPoolExecutor(1, new BasicThreadFactory.Builder().namingPattern("scheduled-pool-%d").daemon(true).build());

    /**
     * 每隔6小时，执行删除缓存影像文件
     */
    public ExternalImageServiceImpl() {
        service.scheduleAtFixedRate(() -> deleteUselessFile(), 0, 6, TimeUnit.HOURS);
    }

    private static Resource createTempFileResource(String fileName, byte[] content) throws IOException {
        File file = new File(new StringBuilder().append(FileUtils.getTempDirectory())
                .append(File.separator)
                .append(UUID.randomUUID().toString())
                .append("eclipse")
                .append(File.separator)
                .append(fileName).toString());
        FileUtils.writeByteArrayToFile(file, content);
        //to upload in-memory bytes use ByteArrayResource instead
        return new FileSystemResource(file);
    }

    @Override
    @IgnoreAopLogPrint
    public ImageFileDTO uploadImage(UploadFileRequest fileRequest) {
        notNull(fileRequest.getMimeType(), "Mime type is required!");
        notNull(fileRequest, "fileRequest can not be null");
        notBlank(fileRequest.getBusinessNo(), "BusinessNo can not be empty");
        notBlank(fileRequest.getName(), "FileName can not be empty");
        notNull(fileRequest.getContent(), "File size can not be 0");
        isTrue(fileRequest.getContent().length > 0, "File size can not be 0");

        try {
            log.info("Uploading image file with request: {}",
                    new ReflectionToStringBuilder(fileRequest, ToStringStyle.SHORT_PREFIX_STYLE)
                            .setExcludeFieldNames("content").toString());

            UriComponentsBuilder builderImage = UriComponentsBuilder.fromHttpUrl(imageUploadUrl + IMAGE_TAIL);

            MultiValueMap<String, Object> params = new LinkedMultiValueMap<>();
            params.add("systemUserId", systemUserId);
            params.add("password", password);
            // 为空时，赋值eclipse的businessType
            params.add("businessType", StringUtils.isBlank(fileRequest.getBusinessType()) ? BUSINESS_TYPE : fileRequest.getBusinessType());
            params.add("businessNo", fileRequest.getBusinessNo());
            params.add("publicRead", fileRequest.getPublicRead());
            params.add("reserveOriginalName", fileRequest.getReserveOriginalName());
            if (isNotEmpty(fileRequest.getTags())) {
                params.add("tags", fileRequest.getTags());
                ImageCategoryQueryRequest imageCategoryQueryRequest = new ImageCategoryQueryRequest();
                imageCategoryQueryRequest.setBusinessType(BUSINESS_TYPE);
                imageCategoryQueryRequest.setBusinessNo(fileRequest.getBusinessNo());
                imageCategoryQueryRequest.setSystemUserId(systemUserId);
                imageCategoryQueryRequest.setPassword(password);
                Response<List<ImageCategoryResponse>> response = imageCategoryService.getImageCategory(imageCategoryQueryRequest);
                log.info("getImageCategory response:{}", JsonUtil.obj2Json(response));
                if (response.isSuccess() && CollectionUtils.isNotEmpty(response.getContent())) {
                    // typeCode：影像目录升级为动态目录后的目录路径标识，根据报案号和影像的分类标签，可以查到对应的映射，如果typeCode未匹配到则认为是老影像目录
                    params.add("typeCode", mappingTypeCode(response.getContent(), fileRequest.getTags()));
                }
            }
            params.set("extendInfo", fileRequest.getExtendInfo());

            // creating an HttpEntity for the binary part
            HttpHeaders pictureHeader = new HttpHeaders();
            pictureHeader.setContentType(MediaType.valueOf(fileRequest.getMimeType()));
            Resource tempResource = createTempFileResource(fileRequest.getName(), fileRequest.getContent());
            HttpEntity<Resource> picturePart = new HttpEntity<>(tempResource, pictureHeader);
            params.add("file", picturePart);
            params.add("systemSource", fileRequest.getSystemSource());

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.MULTIPART_FORM_DATA);

            HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(params, headers);
            ResponseEntity<GenericResponse<ImageFileDTO>> response = fileRestTemplate.exchange(
                    builderImage.toUriString(), HttpMethod.POST, requestEntity,
                    new ParameterizedTypeReference<GenericResponse<ImageFileDTO>>() {
                    });
            if (response == null || response.getBody() == null || response.getStatusCodeValue() != HttpStatus.OK.value()) {
                log.warn("uploadImage failed, response is {}, with uploadFileRequest is {}", response, fileRequest);
                throw new EclipseRuntimeException(ErrorCodeEnum.ERROR_FILE_UPLOAD_FAIL, "调用影像系统发生异常");
            }

            // get Image File DTO
            return response.getBody().getData();
        } catch (Exception e) {
            log.error("Uploaded image file error", e);
            throw new EclipseRuntimeException(ErrorCodeEnum.ERROR_FILE_UPLOAD_FAIL, "调用影像系统发生异常");
        }
    }

    @Override
    @IgnoreAopLogPrint
    public List<ImageFileDTO> listImageFile(String businessNo, String businessType, Map<String, String> extendInfo) {
        notBlank(businessNo, "businessNo is required!");

        QueryFileRequest request = new QueryFileRequest();
        request.setSystemUserId(systemUserId);
        request.setPassword(password);
        request.setBusinessType(StringUtils.isBlank(businessType) ? BUSINESS_TYPE : businessType);
        request.setBusinessNo(businessNo);
        // 填充扩展属性
        populateResultFilter(request, extendInfo);
        Response<List<ImageFileDTO>> response = imageFileService.queryWithUserId(request);
        // get Image File List
        return response.getContent();
    }

    /**
     * 组装扩展属性
     *
     * @param request
     * @param map
     */
    private void populateResultFilter(QueryFileRequest request, Map<String, String> map) {
        if (Objects.isNull(request) || MapUtils.isEmpty(map)) {
            return;
        }

        ResultFilter resultFilter = new ResultFilter();
        for (Map.Entry<String, String> entry : map.entrySet()) {
            resultFilter.setExtendInfoWithIn(entry.getKey(), Collections.singletonList(entry.getValue()));
        }
        request.setResultFilter(resultFilter);
    }

    @Override
    public boolean batchUpdateFileTags(String businessNo, Set<String> removedTags) {
        notBlank(businessNo, "businessNo is required!");
        noNullElements(removedTags, "removedTags is required!");
        BatchUpdateFileTagsRequest request = new BatchUpdateFileTagsRequest();
        request.setSystemUserId(systemUserId);
        request.setPassword(password);
        request.setBusinessType(BUSINESS_TYPE);
        request.setBusinessNo(businessNo);
        request.setRemoved(removedTags);

        try {
            imageFileService.batchUpdateFileTags(request);
            return true;
        } catch (Exception e) {
            MonitorUtil.errorMonitor(new MonitorBean(ChannelEnum.DEFAULT,
                    EventCodeEnum.REST_INVOKE_ERROR,
                    MonitorBean.Status.ERROR)
                    .className(this.getClass().getSimpleName())
                    .methodName("batchUpdateFileTags")
                    .traceId(TracerUtils.getTraceId())
                    .errorMsg(e.getMessage()));
            log.warn("batchUpdateFileTags encountered exception with businessNo is {} and removedTags is {}", businessNo, removedTags);
            return false;
        }
    }

    @Override
    public boolean batchUpdateExtendInfo(String businessNo, Set<Long> ids, Map<String, String> extendInfo) {
        log.info("batchUpdateExtendInfo with businessNo is {} and removedTags is {}", businessNo, extendInfo);

        notBlank(businessNo, "businessNo is required!");
        notEmpty(extendInfo, "exendInfo cannot be empty");

        BatchUpdateExtendInfoRequest request = new BatchUpdateExtendInfoRequest();
        request.setSystemUserId(systemUserId);
        request.setPassword(password);
        request.setBusinessType(BUSINESS_TYPE);
        request.setBusinessNo(businessNo);
        request.setExtendInfoUpdates(extendInfo);
        request.setIds(ids);
        try {
            imageFileService.batchUpdateExtendInfo(request);
            return true;
        } catch (Exception e) {
            MonitorUtil.errorMonitor(new MonitorBean(ChannelEnum.DEFAULT,
                    EventCodeEnum.REST_INVOKE_ERROR,
                    MonitorBean.Status.ERROR)
                    .className(this.getClass().getSimpleName())
                    .methodName("batchUpdateExtendInfo")
                    .traceId(TracerUtils.getTraceId())
                    .errorMsg(e.getMessage()));
            log.warn("batchUpdateExtendInfo encountered exception with request is {}", request, e);
            return false;
        }
    }

    @Override
    public boolean deleteByImageId(String businessNo, Long imageId) {
        notNull(imageId, "imageId is required!");

        DeleteFileRequest request = new DeleteFileRequest();
        request.setSystemUserId(systemUserId);
        request.setPassword(password);
        request.setBusinessType(BUSINESS_TYPE);
        request.setBusinessNo(businessNo);
        request.setId(imageId);

        try {
            Response<Void> response = imageFileService.delete(request);
            if (Objects.isNull(response) || !response.isSuccess()) {
                log.info("The response of deleteByImageId is empty, with request is {}", request);
                return false;
            }

            return true;
        } catch (Exception e) {
            MonitorUtil.errorMonitor(new MonitorBean(ChannelEnum.DEFAULT,
                    EventCodeEnum.REST_INVOKE_ERROR,
                    MonitorBean.Status.ERROR)
                    .className(this.getClass().getSimpleName())
                    .methodName("deleteByImageId")
                    .traceId(TracerUtils.getTraceId())
                    .errorMsg(e.getMessage()));
            log.warn("deleteByImageId encountered exception with request is {}", request, e);
            return false;
        }
    }

    /**
     * 删除文件夹（文件夹创建时间距离当前时间超过六个小时且文件夹以‘eclipse’字符结尾）
     */
    void deleteUselessFile() {
        Arrays.stream(FileUtils.getTempDirectory().listFiles()).
                filter(file -> (file.isDirectory() && (file.lastModified() + SIX_HOUR_TO_MILLISECOND < System.currentTimeMillis()) && file.getName().endsWith("eclipse"))).
                forEach(FileUtils::deleteQuietly);
    }

    @Override
    public void afterPropertiesSet() {
        List<HttpMessageConverter<?>> messageConverters = fileRestTemplate.getMessageConverters();
        fileRestTemplate.setMessageConverters(getAllEncompassingFormHttpMessageConverter(messageConverters));
    }

    private List<HttpMessageConverter<?>> getAllEncompassingFormHttpMessageConverter(List<HttpMessageConverter<?>> messageConverters) {
        if (isEmpty(messageConverters)) {
            return Collections.EMPTY_LIST;
        }

        ImmutableList.Builder<HttpMessageConverter<?>> builder = ImmutableList.builder();
        for (HttpMessageConverter<?> converter : messageConverters) {
            if (converter instanceof AllEncompassingFormHttpMessageConverter) {
                converter = new AllEncompassingFormHttpMessageConverter() {
                    @Override
                    protected String getFilename(Object part) {
                        if (part instanceof Resource) {
                            Resource resource = (Resource) part;
                            //Get resource file name
                            String fileName = resource.getFilename();
                            try {
                                return URLEncoder.encode(truncate(fileName), "UTF-8");
                            } catch (UnsupportedEncodingException e) {
                                e.printStackTrace();
                                return null;
                            }
                        } else {
                            return null;
                        }
                    }
                };
            }
            builder.add(converter);
        }

        return builder.build();
    }

